// Animation pipeline, transformation presentation and appendage-rig tests.
//
// These run in plain Node (no browser) against the real modules and a real skinned glTF:
// the fixture in public/models/characters/_fixture/rig-test.glb is generated by
// scripts/make-rig-fixture.mjs, is original geometry, and is deliberately not registered in
// the character manifest, so it proves the pipeline without pretending to be a character.
//
//   node scripts/test-animation-pipeline.mjs
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { buildRigGlb, FIXTURE_PATH, FIXTURE_JOINTS } from './make-rig-fixture.mjs';
import { resolveRig, classifyBone, CANONICAL_BONES, describeRig, resetRig } from '../public/js/anim/rig_map.js';
import { retargetClip } from '../public/js/anim/animation_loader.js';
import { buildAllClips, retimeClip, CLIP_SPECS } from '../public/js/anim/clip_library.js';
import { AnimationController, attackClipId, attachAnimation } from '../public/js/anim/animation_controller.js';
import { attachSpiderLegs, updateSpiderLegs, spiderLegTips, describeSpiderLegs, POSES, REACH } from '../public/js/anim/spider_legs.js';
import { collectFormSurfaces, applyFormPresentation, clearFormPresentation, formPresentationReport } from '../public/js/anim/form_presentation.js';
import { makeProceduralCharacter } from '../public/js/models.js';
import { MOVESETS } from '../public/js/combat/movesets.js';

let checks = 0;
function check(name, condition, detail = '') {
  assert.ok(condition, `${name}${detail ? ' — ' + detail : ''}`);
  checks++;
  console.log(`  ok  ${name}`);
}

function parseGlb(buffer) {
  return new Promise((ok, fail) => {
    const arrayBuffer = buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength);
    new GLTFLoader().parse(arrayBuffer, '', ok, error => fail(new Error(String(error?.message || error))));
  });
}

function fakeFighter(overrides = {}) {
  return {
    velocity: new THREE.Vector3(),
    isGrounded: true,
    hitstun: 0,
    guardHeld: false,
    guardBreak: 0,
    dodgeTimer: 0,
    flightMode: false,
    attackQueue: [],
    comboStep: 0,
    specialCooldown: 0,
    facing: 1,
    facingZ: 0,
    ...overrides
  };
}

// ---------------------------------------------------------------- fixture integrity
console.log('\n[rig fixture]');
const fixtureBuffer = buildRigGlb();
check('the fixture builds', fixtureBuffer.length > 2000, `${fixtureBuffer.length} bytes`);
if (!existsSync(resolve(FIXTURE_PATH))) {
  console.log('  note: fixture file missing on disk; writing it is the generator\'s job');
}
const onDisk = readFileSync(resolve(FIXTURE_PATH));
check('the checked-in fixture matches the generator', onDisk.length === fixtureBuffer.length, `${onDisk.length} vs ${fixtureBuffer.length}`);

const manifest = JSON.parse(readFileSync(resolve('public/models/characters/manifest.json'), 'utf8'));
const entries = Object.entries(manifest.characters || {});
check('the fixture is not registered as a character', !Object.keys(manifest.characters || {}).some(key => /fixture|rig_test/.test(key)));
// Goku, Iron Man and Iron Spider ship an ORIGINAL stylised alternative authored in this
// repository (assets/blender/build_roster_models.py). Those exports are real rigs, but they
// render worse than the authored bodies in public/js/characters/sculpted.js, so the entries are
// disabled and the game keeps the authored body. The rule this guards is that the disabled state
// is deliberate: the file must exist and pass the offline inspector, the entry must record why it
// is off, and the licensed source it stands in for must still be named.
for (const [key, alt] of [['goku', 'goku-alt'], ['iron_man_tony_stark', 'iron-man-alt'], ['iron_spider', 'iron-spider-alt']]) {
  const superseded = manifest.characters[alt];
  check(`${alt} is kept disabled, with the reason it was superseded`,
    superseded?.enabled === false && superseded.assetKind === 'original-alternative'
      && Boolean(superseded.pendingLicensedAsset) && Boolean(superseded.verified?.rendersWorseThan),
    `${alt}: enabled=${superseded?.enabled} kind=${superseded?.assetKind} pending=${Boolean(superseded?.pendingLicensedAsset)} reason=${Boolean(superseded?.verified?.rendersWorseThan)}`);
  check(`${alt} points at a file that is really on disk`,
    Boolean(superseded?.url) && existsSync(resolve('public', String(superseded.url).replace(/^\//, ''))),
    String(superseded?.url || ''));
  const entry = manifest.characters[key];
  check(`${key} is served by the validated roster body`,
    entry?.enabled === true && /\/models\/characters\/roster\//.test(String(entry.url || '')),
    `${key}: enabled=${entry?.enabled} url=${entry?.url}`);
  const target = entry?.urls?.[0] || entry?.url || '';
  check(`${key} points at a file that is really on disk`,
    Boolean(target) && existsSync(resolve('public', target.replace(/^\//, ''))), target);
  check(`${key} still names the licensed source it stands in for`,
    Boolean(entry?.pendingLicensedAsset), String(entry?.pendingLicensedAsset || ''));
  check(`${key} records how the export was verified`,
    Boolean(entry.verified?.inspectedWith) && Boolean(entry.verified?.rosterTest),
    JSON.stringify(entry.verified || null));
}
// And the general rule the flagship case is an exception to: every enabled entry resolves to a
// file, and no entry claims to be the licensed character model without it.
for (const [key, entry] of entries) {
  if (entry.enabled !== true) continue;
  const target = entry.urls?.[0] || entry.url || '';
  check(`${key} is enabled only because its asset exists`, existsSync(resolve('public', target.replace(/^\//, ''))), target);
  check(`${key} does not claim to be the licensed source asset`, entry.assetKind !== 'licensed', String(entry.assetKind));
}

// ---------------------------------------------------------------- skinned glTF -> canonical rig
console.log('\n[skinned glTF]');
const gltf = await parseGlb(onDisk);
let skinned = null, bones = 0;
gltf.scene.traverse(node => {
  if (node.isSkinnedMesh) skinned = node;
  if (node.isBone) bones++;
});
check('the fixture is a real skinned mesh', Boolean(skinned) && skinned.skeleton?.bones?.length === FIXTURE_JOINTS, `${skinned?.skeleton?.bones?.length} skeleton bones`);
check('every fixture joint is in the scene graph', bones === FIXTURE_JOINTS, `${bones} bones traversed`);
check('the fixture ships two clips', gltf.animations.length === 2, gltf.animations.map(c => c.name).join(', '));

const rig = resolveRig(gltf.scene);
check('the rig binds as a bone rig, not a prefab', rig?.kind === 'bone', rig?.kind);
check('all eleven canonical bones bind', rig.boundCount === CANONICAL_BONES.length && rig.missing.length === 0,
  `bound ${rig.boundCount}, missing ${rig.missing.join(',') || 'none'}`);
check('Mixamo names classify to the canonical bones',
  classifyBone('mixamorig:LeftArm') === 'leftArm' && classifyBone('mixamorig:LeftLeg') === 'leftShin',
  `${classifyBone('mixamorig:LeftArm')}, ${classifyBone('mixamorig:LeftLeg')}`);
const rigReport = describeRig(rig);
check('the bound rig measures a real body height', rigReport.height > 1.4 && rigReport.height < 2.4, JSON.stringify(rigReport));

// ---------------------------------------------------------------- retargeting
console.log('\n[retargeting]');
const idleSource = gltf.animations.find(clip => clip.name === 'Idle');
const retargeted = retargetClip(idleSource, { name: 'idle' });
check('an external clip retargets into canonical bone space', retargeted?.tracks.length === 2,
  retargeted ? retargeted.tracks.map(t => t.name).join(', ') : 'null');
check('retargeted tracks target the safe bone names',
  retargeted.tracks.every(track => track.name.startsWith('bs_') && track.name.endsWith('.quaternion')),
  retargeted.tracks.map(t => t.name).join(', '));
check('retargeting drops position and scale tracks so clips cannot move the fighter',
  retargeted.tracks.every(track => !/\.position$|\.scale$/.test(track.name)));
check('retargeting records provenance', retargeted.userData.origin === 'external' && retargeted.userData.sourceClip === 'Idle');

const library = buildAllClips(rig);
check('the authored clip library compiles against the imported rig', library.size === Object.keys(CLIP_SPECS).length, `${library.size} clips`);
check('the library covers locomotion, combat, defence, flight and objectives',
  ['idle', 'walk', 'run', 'jab', 'heavy_punch', 'block', 'dodge_right', 'hit_heavy', 'knockdown', 'get_up', 'fly_loop', 'knockout']
    .every(id => library.has(id)));

const peakTest = retimeClip(library.get('jab'), 0.4, 0.5);
check('attack clips retime so the strike peak lands on the gameplay window',
  Math.abs(peakTest.duration - 0.4) < 0.001, `${peakTest.duration}`);
check('move kinds map onto authored clips',
  attackClipId({ kind: 'grab' }) === 'grab' && attackClipId({ kind: 'throw' }) === 'throw'
  && attackClipId({ kind: 'heavy' }, { comboStep: 3 }) === 'spinning_kick'
  && attackClipId({ kind: 'melee' }, { comboStep: 1 }) === 'jab');

// ---------------------------------------------------------------- controller drives the rig
console.log('\n[animation controller]');
const fighter = fakeFighter();
const controller = new AnimationController(gltf.scene, fighter, {});
check('the controller is ready on a real rig', controller.ready, controller.describe().rig);
const shoulder = rig.joints.rightArm;
const before = shoulder.quaternion.clone();
for (let i = 0; i < 12; i++) { fighter.velocity.set(6.5, 0, 0); controller.update(1 / 60); }
check('clips actually rotate the skeleton', shoulder.quaternion.angleTo(before) > 0.01,
  `${shoulder.quaternion.angleTo(before).toFixed(4)} rad`);
check('locomotion selects a walk/run clip', ['walk', 'run', 'sprint'].includes(controller.describe().active), controller.describe().active);

fighter.attackQueue = [{ kind: 'melee', start: 0.05, end: 0.16, total: 0.32, hit: false, t: 0 }];
controller.update(1 / 60);
const attackState = controller.describe();
check('an attack switches to an attack clip', attackState.active === 'jab', attackState.active);
check('the attack clip is retimed to the move', attackState.retimes > 0, `${attackState.retimes} retimes`);

fighter.attackQueue = [];
fighter.hitstun = 0.5;
controller.update(1 / 60);
check('hitstun overrides the attack clip', /hit_/.test(controller.describe().active), controller.describe().active);

check('the hit clip is held rather than cancelled on the next frame', /hit_/.test(controller.describe().active), 'held by its one-shot lock');
fighter.hitstun = 0;
fighter.isGrounded = false;
fighter.velocity.set(0, 6, 0);
// The hit one-shot owns the body for its authored duration, then the airborne state takes over.
for (let i = 0; i < 45; i++) controller.update(1 / 60);
check('leaving the ground plays an airborne clip', ['jump', 'fall', 'double_jump'].includes(controller.describe().active), controller.describe().active);

check('every clip the controller reports carries provenance',
  Object.keys(CLIP_SPECS).length >= 30 && controller.clips.size === library.size);

// ------------------------------------------------------- motion personality
// The overlay is only worth having if it (a) is driven by the fighter's identity, (b) really
// changes the pose on top of the clip, and (c) leaves down states and unlisted identities alone.
console.log('\n[motion personality]');
const gokuGlb = await parseGlb(readFileSync(resolve(FIXTURE_PATH)));
const plainGlb = await parseGlb(readFileSync(resolve(FIXTURE_PATH)));
const gokuRig = resolveRig(gokuGlb.scene);
const plainRig = resolveRig(plainGlb.scene);
const gokuController = new AnimationController(gokuGlb.scene, fakeFighter({ identityKey: 'goku' }), {});
const plainController = new AnimationController(plainGlb.scene, fakeFighter(), {});
check('a fighter carries its identity into the controller', gokuController.style?.id === 'goku',
  String(gokuController.style?.id));
check('an unlisted identity stays on the neutral style', plainController.style?.id === 'default',
  String(plainController.style?.id));
check('the personality is reported for diagnostics', gokuController.describe().personality === 'goku',
  String(gokuController.describe().personality));
for (let i = 0; i < 90; i++) { gokuController.update(1 / 60); plainController.update(1 / 60); }
const headDrift = gokuRig.joints.head.quaternion.angleTo(plainRig.joints.head.quaternion);
check('the overlay really moves the rig on top of the clip', headDrift > 0.005, `${headDrift.toFixed(4)} rad`);
check('both controllers are playing the same clip, so the difference is the personality',
  gokuController.describe().active === plainController.describe().active,
  `${gokuController.describe().active} / ${plainController.describe().active}`);
const heldHead = gokuRig.joints.head.quaternion.clone();
gokuController._active = 'knockout';
gokuController._applyPersonality(1 / 60);
check('down states are left to the clip, not softened by the overlay',
  gokuRig.joints.head.quaternion.angleTo(heldHead) < 1e-6);
gokuController._active = 'fighting_idle';
gokuController.dispose();
plainController.dispose();

// A rig with no skeleton must not be forced through the clip layer.
const plain = new THREE.Group();
plain.add(new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1)));
check('a model with no rig refuses the clip layer instead of throwing', attachAnimation(plain, fakeFighter()) === null);
controller.dispose();
resetRig(rig);
check('disposing restores the bind pose', shoulder.quaternion.angleTo(before) < 0.01);

// ---------------------------------------------------------------- Iron Spider appendages
console.log('\n[Iron Spider legs]');
const spiderBody = makeProceduralCharacter('cyborg', 'Iron Spider');
const spiderRig = spiderBody.userData.spiderLegs;
check('the Iron Spider body mounts the leg rig', Boolean(spiderRig) && spiderRig.legs.length === 4, `${spiderRig?.legs.length} legs`);
check('each leg is a three-joint chain', spiderRig.legs.every(leg => leg.coxa && leg.femur && leg.tibia && leg.tip));
check('the rig reports twelve joints and a real reach', describeSpiderLegs(spiderRig).joints === 12 && REACH > 1.5,
  JSON.stringify(describeSpiderLegs(spiderRig)));

const otherBody = makeProceduralCharacter('warrior', 'Superman');
check('only Iron Spider gets appendages', !otherBody.userData.spiderLegs);

const spiderFighter = fakeFighter();
spiderFighter.model = spiderBody;
spiderFighter.t = 0;
const foldedTips = spiderLegTips(spiderRig);
spiderFighter.legStrike = 1.3;
for (let i = 0; i < 15; i++) updateSpiderLegs(spiderFighter, 1 / 60);
const strikeTips = spiderLegTips(spiderRig);
const reachBefore = Math.max(...foldedTips.map(tip => Math.hypot(tip.x, tip.z)));
const reachDuring = Math.max(...strikeTips.map(tip => Math.hypot(tip.x, tip.z)));
check('the sweep drives the legs into the strike pose', spiderRig.state === 'strike', spiderRig.state);
check('the strike pose throws the tips further out than the folded pose', reachDuring > reachBefore + 0.15,
  `${reachBefore.toFixed(2)} m -> ${reachDuring.toFixed(2)} m`);
check('leg tips stay within a sane limb length', reachDuring < REACH + 0.6, `${reachDuring.toFixed(2)} m vs reach ${REACH.toFixed(2)}`);

spiderFighter.legStrike = 0;
for (let i = 0; i < 90; i++) updateSpiderLegs(spiderFighter, 1 / 60);
check('the legs relax once the sweep ends', spiderRig.state !== 'strike', spiderRig.state);
check('the pose writer keeps running every frame', spiderRig.poseWrites > 90, `${spiderRig.poseWrites} writes`);

spiderFighter.guardHeld = true;
updateSpiderLegs(spiderFighter, 1 / 60);
check('guarding raises the legs', spiderRig.state === 'guard', spiderRig.state);
spiderFighter.guardHeld = false;

const stumble = fakeFighter({ hitstun: 0.6 });
const hovering = fakeFighter({ flightMode: true, isGrounded: false, velocity: new THREE.Vector3(0, 1, 0) });
const dropping = fakeFighter({ isGrounded: false, velocity: new THREE.Vector3(0, -8, 0) });
const posesSeen = [stumble, hovering, dropping].map(f => {
  f.model = spiderBody;
  updateSpiderLegs(f, 1 / 60);
  return spiderRig.state;
});
check('hitstun, flight and a hard fall each pick a different pose', new Set(posesSeen).size === 3, posesSeen.join(', '));
const dodging = fakeFighter({ dodgeTimer: 0.3 });
dodging.model = spiderBody;
updateSpiderLegs(dodging, 1 / 60);
check('a dodge uses the stagger pose', spiderRig.state === 'stagger', spiderRig.state);

// ---------------------------------------------------------------- transformation presentation
console.log('\n[form presentation]');
const gokuBody = makeProceduralCharacter('warrior', 'Goku');
const surfaces = collectFormSurfaces(gokuBody);
check('Goku’s body declares hair and accent surfaces', surfaces.has('hair') && surfaces.has('accent'),
  [...surfaces.keys()].join(', '));
const hairEntry = surfaces.get('hair')[0];
const baseHairColor = hairEntry.material.color.getHex();
const baseHairIntensity = hairEntry.material.emissiveIntensity;
const baseHairScale = hairEntry.mesh.scale.x;

const goku = { model: gokuBody, t: 0 };
const superSaiyan = MOVESETS.vegeta.form; // same authored shape as Goku's forms
const applied = applyFormPresentation(goku, superSaiyan);
check('a form changes real surfaces', applied.applied && applied.surfaces > 0, JSON.stringify(applied));
check('the hair is recoloured, not the whole body', hairEntry.material.color.getHex() === 0xf7d452,
  '#' + hairEntry.material.color.getHexString());
check('the hair silhouette grows', hairEntry.mesh.scale.x > baseHairScale, `${baseHairScale} -> ${hairEntry.mesh.scale.x}`);
check('the form report names the surfaces it touched', formPresentationReport(goku).tags.includes('hair'));

clearFormPresentation(goku);
check('expiry restores the authored hair colour', hairEntry.material.color.getHex() === baseHairColor);
check('expiry restores the authored emissive intensity', hairEntry.material.emissiveIntensity === baseHairIntensity,
  `${hairEntry.material.emissiveIntensity}`);
check('expiry restores the authored hair scale', hairEntry.mesh.scale.x === baseHairScale);
check('clearing twice is safe', clearFormPresentation(goku) === false);

const ironBody = makeProceduralCharacter('cyborg', 'Iron Man (Tony Stark)');
const ironSurfaces = collectFormSurfaces(ironBody);
check('Iron Man’s body declares a reactor surface', ironSurfaces.has('reactor'), [...ironSurfaces.keys()].join(', '));
const reactor = ironSurfaces.get('reactor')[0];
const baseReactorColor = reactor.material.color.getHex();
const ironMan = { model: ironBody, t: 0 };
applyFormPresentation(ironMan, MOVESETS.iron_man_tony_stark.form);
check('overdrive drives the reactor white-hot', reactor.material.color.getHex() === 0xe8feff, '#' + reactor.material.color.getHexString());
check('overdrive brightens the emissive', reactor.material.emissiveIntensity > 3, `${reactor.material.emissiveIntensity}`);
clearFormPresentation(ironMan);
check('overdrive restores the reactor', reactor.material.color.getHex() === baseReactorColor && reactor.material.emissiveIntensity < 3);

const ironSpiderBody = makeProceduralCharacter('cyborg', 'Iron Spider');
const spiderSurfaces = collectFormSurfaces(ironSpiderBody);
check('Iron Spider’s appendages are form surfaces', spiderSurfaces.has('appendage'), [...spiderSurfaces.keys()].join(', '));
const ironSpider = { model: ironSpiderBody, t: 0 };
const appendage = spiderSurfaces.get('appendage')[0];
const baseAppendage = appendage.material.color.getHex();
applyFormPresentation(ironSpider, MOVESETS.iron_spider.form);
check('the assault protocol heats the legs', appendage.material.color.getHex() === 0xffe89a, '#' + appendage.material.color.getHexString());
clearFormPresentation(ironSpider);
check('the assault protocol restores the legs', appendage.material.color.getHex() === baseAppendage);

// Forms that carry no look must not touch a body at all.
const plainForm = { id: 'no-look' };
check('a form without an authored look leaves the body alone', applyFormPresentation({ model: gokuBody }, plainForm).applied === false);

// Every form that does author a look must only name real surfaces.
const SURFACE_TAGS = new Set(['hair', 'reactor', 'appendage', 'accent']);
for (const [key, set] of Object.entries(MOVESETS)) {
  const look = set.form?.look;
  if (!look) continue;
  const tags = Object.keys(look);
  check(`${key} form look only uses known surfaces`, tags.every(tag => SURFACE_TAGS.has(tag)), tags.join(', '));
}

console.log(`\n${checks} checks passed`);
